[{"order":1,"type":"heading","text":"React Router: Setting Up Navigation"},{"order":2,"type":"paragraph","text":"React Router is the standard library for routing in React applications. It enables navigation between different views or components within your application without requiring full page reloads. This tutorial will guide you through setting up React Router and implementing basic navigation."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Node.js and npm (Node Package Manager) installed"},{"order":5,"type":"bullet_point","text":"Basic understanding of React.js"},{"order":6,"type":"subheading","text":"Step 1: Create a New React Application"},{"order":7,"type":"paragraph","text":"If you don't have an existing React project, create a new one using Create React App:"},{"order":8,"type":"code","text":"npx create-react-app react-router-tutorial
cd react-router-tutorial"},{"order":9,"type":"subheading","text":"Step 2: Install React Router"},{"order":10,"type":"paragraph","text":"Install the `react-router-dom` package, which provides the necessary components for web-based routing:"},{"order":11,"type":"code","text":"npm install react-router-dom"},{"order":12,"type":"subheading","text":"Step 3: Set Up the Router"},{"order":13,"type":"paragraph","text":"Open `src/App.js` and modify it to include the `BrowserRouter`, `Route`, and `Link` components. `BrowserRouter` enables the routing functionality, `Route` maps a URL path to a specific component, and `Link` creates navigation links."},{"order":14,"type":"code","text":"import React from 'react';
import { BrowserRouter as Router, Route, Link, Routes } from 'react-router-dom';

function Home() {
  return <h2>Home</h2>;
}

function About() {
  return <h2>About</h2>;
}

function App() {
  return (
    <Router>
      <div>
        <nav>
          <ul>
            <li>
              <Link to="/">Home</Link>
            </li>
            <li>
              <Link to="/about">About</Link>
            </li>
          </ul>
        </nav>

        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/about" element={<About />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;"},{"order":15,"type":"paragraph","text":"Explanation:"},{"order":16,"type":"bullet_point","text":"`BrowserRouter`:  Wraps the entire application to enable routing."},{"order":17,"type":"bullet_point","text":"`Link`: Used to create links to different routes.  The `to` prop specifies the path."},{"order":18,"type":"bullet_point","text":"`Route`:  Defines a mapping between a URL path (specified by the `path` prop) and a component to render (specified by the `element` prop)."},{"order":19,"type":"bullet_point","text":"`Routes`: A container for `Route` elements. It ensures that only one route is rendered at a time."},{"order":20,"type":"subheading","text":"Step 4: Run the Application"},{"order":21,"type":"paragraph","text":"Start the development server:"},{"order":22,"type":"code","text":"npm start"},{"order":23,"type":"paragraph","text":"Open your browser and navigate to `http://localhost:3000`. You should see the navigation links and the content for the Home page. Clicking the 'About' link should navigate you to the About page."},{"order":24,"type":"subheading","text":"Step 5: Adding More Routes"},{"order":25,"type":"paragraph","text":"You can add more routes to your application by creating new components and adding corresponding `Route` elements within the `Routes` component. For example, let's add a `Contact` component:"},{"order":26,"type":"code","text":"import React from 'react';
import { BrowserRouter as Router, Route, Link, Routes } from 'react-router-dom';

function Home() {
  return <h2>Home</h2>;
}

function About() {
  return <h2>About</h2>;
}

function Contact() {
  return <h2>Contact</h2>;
}

function App() {
  return (
    <Router>
      <div>
        <nav>
          <ul>
            <li>
              <Link to="/">Home</Link>
            </li>
            <li>
              <Link to="/about">About</Link>
            </li>
            <li>
              <Link to="/contact">Contact</Link>
            </li>
          </ul>
        </nav>

        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/about" element={<About />} />
          <Route path="/contact" element={<Contact />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;"},{"order":27,"type":"subheading","text":"Step 6: Using Route Parameters"},{"order":28,"type":"paragraph","text":"React Router allows you to define routes with parameters. This is useful for displaying dynamic content based on the URL.  For example, to display user profiles:"},{"order":29,"type":"code","text":"import React from 'react';
import { BrowserRouter as Router, Route, Link, Routes, useParams } from 'react-router-dom';

function Home() {
  return <h2>Home</h2>;
}

function About() {
  return <h2>About</h2>;
}

function User() {
  const { userId } = useParams();
  return <h2>User ID: {userId}</h2>;
}

function App() {
  return (
    <Router>
      <div>
        <nav>
          <ul>
            <li>
              <Link to="/">Home</Link>
            </li>
            <li>
              <Link to="/about">About</Link>
            </li>
            <li>
              <Link to="/user/123">User 123</Link>
            </li>
            <li>
              <Link to="/user/456">User 456</Link>
            </li>
          </ul>
        </nav>

        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/about" element={<About />} />
          <Route path="/user/:userId" element={<User />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;"},{"order":30,"type":"paragraph","text":"Explanation:"},{"order":31,"type":"bullet_point","text":"`useParams`: This hook allows you to access the parameters defined in the route. In this case, `:userId` is the parameter."},{"order":32,"type":"bullet_point","text":"The `Route` `path` `/user/:userId` defines a route that matches URLs like `/user/123` or `/user/456`. The value after `/user/` is captured as the `userId` parameter."},{"order":33,"type":"subheading","text":"Conclusion"},{"order":34,"type":"paragraph","text":"This tutorial covered the basics of setting up navigation with React Router. You learned how to install React Router, define routes, create navigation links, and use route parameters. With these fundamentals, you can build more complex and dynamic navigation structures in your React applications."}]
